import React from 'react';
import {observer} from 'mobx-react';
import {action} from 'mobx';

// Define the CreateObjectModel and its properties
class CreateObjectModel {
  availableAssets = [
    'Sphere',
    'Cube',
    'Plane',
  ];

  selectedAsset = '';

  // Function to create an object with the given name
  @action
  createObject(name) {
    console.log(`Creating object ${name}`);
  }

  // Function to clean up the scene
  @action
  cleanupScene() {
    console.log('Cleaning up scene');
  }
}

const CreateObjectView = observer(({model}) => {
  // Render the UI components using the model state
  return (
    <div id="create-object">
      <label htmlFor="asset-input" id="asset-label">Asset:</label>
      <input type="text" id="asset-input" value={model.selectedAsset} onChange={e => model.selectedAsset = e.target.value} />
      <button id="create-btn" onClick={() => model.createObject(model.selectedAsset)}>Create</button>

      <div id="assets-list">
        {model.availableAssets.map(asset => (
          <div key={asset} className="asset" data-asset={asset}>
            {asset}
          </div>
        ))}
      </div>

      <button id="cleanup-scene-btn" onClick={model.cleanupScene}>Cleanup scene</button>
    </div>
  );
});

export default CreateObjectView;
```

