Sure! Here's a simple JavaScript function that takes a string as input and returns a new string with the order of adjectives reversed:

```js
function reverseAdjectives(str) {
  // Split the string into an array of words based on spaces
  const words = str.split(" ");

  // Find the indices of the first adjective and the last space before it
  let firstAdjIdx = -1;
  let lastSpaceBeforeAdjIdx = -1;
  for (let i = 0; i < words.length; i++) {
    if (isAdjective(words[i])) {
      firstAdjIdx = i;
    }
    if (i > 0 && isSpace(words[i - 1]) && !isAdjective(words[i - 2])) {
      lastSpaceBeforeAdjIdx = i - 1;
    }
  }

  // If there are no adjectives, return the original string
  if (firstAdjIdx === -1) {
    return str;
  }

  // Swap the positions of the first adjective and the last space before it
  const temp = words[firstAdjIdx];
  words[firstAdjIdx] = words[lastSpaceBeforeAdjIdx];
  words[lastSpaceBeforeAdjIdx] = temp;

  // Join the words back into a string and return it
  return words.join(" ");
}

// Helper functions to check whether a word is an adjective or a space
function isAdjective(word) {
  return /^[a-z]+[a-z'-]{0,3}[a-z]+$/.test(word);
}

function isSpace(char) {
  return char === " ";
}
```

