#include <iomanip> // required for setprecision() function

int main() {
    const double ORIGINAL_PRICE = 1000;
    const double RESIDUAL_VALUE = 200;
    const double AGREED_REFUND = 600;

    double actualValueOfProduct = ORIGINAL_PRICE - RESIDUAL_VALUE;
    double percentageOfRefund = (AGREED_REFUND / actualValueOfProduct) * 100;

    std::cout << "The agreed refund amount is: " << AGREED_REFUND << ".\n";
    std::cout << "The actual value of the product is: " << actualValueOfProduct << ".\n";
    std::cout << "The percentage of refund is: " << std::fixed << std::setprecision(2) << percentageOfRefund << "%\n";

    return 0;
}
```

