    start, end = 0, 1
    for I in range(len(s)):
        # Palindromes centered around i
        l1, r1 = i, i
        while l1 >= 0 and r1 < len(s) and s[l1] == s[r1]:
            if r1 - l1 + 1 > end - start:
                start, end = l1, r1
        # Palindromes centered around i and j
        l2, r2 = i, i+1
        while l2 >= 0 and r2 < len(s) and s[l2] == s[r2]:
            if r2 - l2 + 1 > end - start:
                start, end = l2, r2
    return s[start:end+1]

print(longest_palindrome("babad")) # Output: "bab"
print(longest_palindrome("cbbd")) # Output: "bb"
print(longest_palindrome("a")) # Output: "a"
print(longest_palindrome("ooqoyqoooqqqoyy")) # Output: "qoyqoo"
```

