enum Homophone: String {
    case their = "there" // Commonly confused with "there"
    case theyre = "they're" // Commonly confused with "they are"
    case your = "you're" // Commonly confused with "you are"
    case weed = "wed" // Less common but still confusing
}

extension String {
    func replaceHomophones() -> String {
        var result = self
        for homophone in Homophone.allCases {
            let pattern = try! NSRegularExpression(pattern: "\\b\(homophone.rawValue)\\b")
            result = pattern.stringByReplacingMatches(in: result, options: [], range: NSRange(location: 0, length: result.utf16.count), withTemplate: homophone.rawValue)
        }
        return result
    }
