To address this task, we will create a dictionary to store the correct words for each homophone. Then, we will iterate through the passage line by line, replacing any misused homophones with their correct counterparts from the dictionary.

Here's the code implementation:

```swift
let homophones = [
    "there": "they're", "their": "there", "they're": "there", "your": "you're",
    "weather": "whether", "know": "no", "sea": "see", "good": "hood", "too": "to",
    "right": "rite", "aloud": "allout", "knot": "not", "do": "dew", "sum": "some",
    "yew": "you", "bee": "be", "true": "through", "seems": "seam", "weight": "wait"
]

func replaceHomophones(in string: String) -> String {
    var result = ""
    let lines = string.components(separatedBy: .newlines)

    for line in lines {
        var newLine = ""

        for (i, word) in line.split(separator: " ") {
            guard !word.isEmpty else { continue } // Skip empty spaces

            let replacement = homophones[String(word), default: word] // Try to find replacement
            newLine += replacement // Add replacement to new line
            newLine += " "
        }

        result += "\(newLine)\n" // Add new line to result
    }

    return result
}

// Example usage
