response:
Here's a possible implementation of bubble sort in C++ that meets your requirements:

```cpp
#include <iostream>
#include <cstring>
#include <cstdio>
#include <nlohmann/json.hpp>

namespace json = nlohmann;

void bubbleSort(int arr[], int size) {
    bool swapped = true;
    for (int I = 0; I < size - 1 && swapped; ++i) {
        swapped = false;
        for (int j = 0; j < size - i - 1; ++j) {
            if (arr[j] > arr[j+1]) {
                int temp = arr[j];
                arr[j] = arr[j+1];
