response:
Here's a C++ implementation of bubble sort for your given use case:

```cpp
#include <iostream>
#include <nlohmann/json.hpp>
#include <vector>

namespace json = nlohmann;

void bubbleSort(std::vector<int>& arr) {
    int n = arr.size();
    bool swapped = true;

    while (swapped) {
        swapped = false;

        for (int I = 0; I < n - 1; i++) {
            if (arr[i] > arr[i + 1]) {
                std::swap(arr[i], arr[i + 1]);
                swapped = true;
            }
        }

        --n; // Reduce size of array since we've already sorted the last element
    }
}

// Example usage:
int main() {
    json j;
    j["array"] = {5, 2, 9, 1, 5, 6};
    std::cout << j.dump() << std::endl; // Print unsorted JSON array

    bubbleSort(j["array"].get<std::vector<int>>()); // Sort the array in-place

    std::cout << j.dump() << std::endl; // Print sorted JSON array

    return 0;
}
```

