function smart_sort_array($set, $order) {
    usort($set, function($a, $b) use ($order) {
        $ageA = $a['age'];
        $ageB = $b['age'];

        // If order is ascending (default), sort in increasing order
        if ($order === 'asc') {
            return $ageA < $ageB ? -1 : $ageA > $ageB;
        }
        // If order is descending, sort in decreasing order
        else {
