Here's a possible implementation:

```js
function getMatchingOptions(options, searchKey, searchValue) {
  const keys = searchKey.split('.');
  let obj = options;

  // Traverse object hierarchy by keys
  for (let I = 0; I < keys.length - 1; i++) {
    if (!obj[keys[i]]) {
      return [];
    }
    obj = obj[keys[i]];
  }

  // Filter options with matching value at last key
  const lastKey = keys[keys.length - 1];
  const filteredOptions = Object.values(obj).filter(({ [lastKey]: val }) => val === searchValue);

  // Create new options objects with updated values
  const matchingOptions = filteredOptions.map(option => {
    const newOption = { ...option };
    const updatedKeys = keys.slice(0, -1);

    // Update parent object properties with current key as key
    updatedKeys.forEach((key, index) => {
      const parentObj = {};
      for (let j = 0; j <= index; j++) {
        parentObj[keys[j]] = obj[keys[j]];
      }

      newOption[updatedKeys.slice(0, index + 1).join('.')] = parentObj;
    });

    // Remove last key from updatedKeys and update option value
    delete newOption[lastKey];
    newOption[updatedKeys.join('.')] = searchValue;

    return newOption;
  });

  return matchingOptions;
}
```

This function takes three arguments: `options`, which is the object containing the nested options you want to filter; `searchKey`, which is the path of the nested property you're searching for; and `searchValue`, which is the value you're looking for in that property. The function returns an array containing all the options that match the search criteria.

The function first splits the `searchKey` into an array of keys separated by dots, and then traverses the `options` object hierarchy using those keys. If any key is missing or doesn't exist, it immediately returns an empty array.

Here's a JavaScript function that takes a dot-notated string as input and returns an array of objects with matching values for a given nested key:

```js
function getNestedObjects(obj, keyPath, value) {
  const keys = keyPath.split(".");
  let currentObj = obj;
  let result = [];

  for (let I = 0; I < keys.length - 1; i++) {
    if (!currentObj[keys[i]]) {
      return result; // early exit if nested object doesn't exist
    }
    currentObj = currentObj[keys[i]];
  }

  const lastKey = keys[keys.length - 1];
  const nestedValues = Object.values(currentObj[lastKey]).filter(item => item === value);

  nestedValues.forEach(nestedValue => {
    const nestedObject = { ...currentObj };
    nestedObject[keyPath] = nestedValue;
    result.push(nestedObject);
  });

  return result;
}

