type StructInfo struct {
	Name    string
	Type    reflect.Type
	Schema *avro.Schema
}

func initStructInfo(t reflect.Type) (*StructInfo, error) {
	info := &StructInfo{
		Name: t.Name(),
	}
	if !t.IsNamed() {
		return nil, errors.New("struct should have a name")
	}
	info.Type = t
	info.Schema = avro.NewSchema()
	for i, fld := range t.Fields() {
		fieldSchema, err := initFieldSchema(&fld)
		if err != nil {
			return nil, fmt.Errorf("error parsing field %d: %w", i+1, err)
		}
		info.Schema.AddField(*fieldSchema)
	}
	return info, nil
}

