  events <- list()
  for (i in seq_along(doc$children)) {
    if (xmlAttrs(doc$children[[i]])$type == "event") {
      date <- as.Date(xmlValue(xmlChildren(doc$children[[i]])$date), format="%Y-%m-%d")
      name <- xmlValue(xmlChildren(doc$children[[i]])$name)
      description <- xmlValue(xmlChildren(doc$children[[i]])$description)
      events[[i]] <- cbind(date, name, description)
    }
  }

  return(events)
}
```

