  xml_doc <- htmlTreeParse(file_path)
  data <- vector("list", length = xmlSize(xml_doc))
  current_year <- NULL

  # Extract year and relevant data
  for (i in seq_len(xmlSize(xml_doc))) {
    if (!is.null(xmlGetAttr(getNode(xml_doc), "year"))) {
      year <- as.numeric(xmlGetAttr(getNode(xml_doc), "year"))

      # Check if current year is same as previous year
      if (!is.null(current_year) && year != current_year) {
        # If not, append current year and data to output list
        data[[length(data)]] <- cbind(current_year, tail(data[-length(data):1], -1))
        current_year <- NULL
      }

      # Set current year and add new data to list
      current_year <- year
      data[[length(data)]] <- xmlValue(getNode(xml_doc)[i])
    }
  }

  # Append last set of data (if any) to output list
  if (!is.null(current_year)) {
    data[[length(data)]] <- cbind(current_year, tail(data[-length(data):1], -1))
  }

  return(do.call(rbind, data))
}
```

