    selectedIndividuals = sort(rand(populationSize), 'descend') * length(fitnesses);
    parentIndices = floor(selectedIndividuals) - 1;

    % Apply selection pressure (chance that less fit individuals are not chosen)
    selectionIndices = mod(parentIndices + 1, populationSize) .* (1 - selectionPressure) + parentIndices .* selectionPressure;

    % Compute offspring genotypes through reproduction and mutation
    childGenotypes = traits(selectionIndices(:,1)) + traits(selectionIndices(:,2));
    childGenotypes = max(min(childGenotypes, 2), -2); % Limit gene expression to range [-2, 2]
    childGenotypes = childGenotypes .* (1 - mutationRate) + randn(size(childGenotypes)) .* mutationRate;

    % Update genotypes of parents with new offspring genotypes
    traits(parentIndices(:,1), :) = childGenotypes(:,1);
    traits(parentIndices(:,2), :) = childGenotypes(:,2);

    % Compute new fitness scores based on updated genotypes
    newFitnesses = exp(traits);

    % Update fitnesses and calculate new generation average
    fitnesses = newFitnesses;
    avgNewGenerationFitness = mean(newFitnesses);
end

% Plot evolution of average fitness over time
figure
