  // start capturing frames from the camera
  videostream.onactive = function () {
    console.log("camera active");
    videostream.start();
  };

  // stop capturing frames from the camera
  videostream.oninactive = function () {
    console.log("camera inactive");
    videostream.stop();
  };
});
