import java.time.Duration;
import java.time.ZoneId;
import java.time.ZonedDateTime;
import java.time.ZoneOffset;
import java.time.format.DateTimeFormatter;

public class DateDurationCalculator {
    public static void main(String[] args) {
        // Convert input strings to UTC format
        String startStr = "2022-01-01T10:00:00Z";
        String endStr = "2022-01-01T15:30:00Z";

        // Parse input strings into ZonedDateTime objects using UTC as the default time zone
        ZonedDateTime startUTC = ZonedDateTime.parse(startStr);
        ZonedDateTime endUTC = ZonedDateTime.parse(endStr);

        // Create a time zone object for the desired destination time zone
        ZoneId destinationTimeZone = ZoneId.of("America/New_York");

        // Convert start and end times to the desired destination time zone
        ZonedDateTime startDest = startUTC.withZoneSameInstant(destinationTimeZone);
        ZonedDateTime endDest = endUTC.withZoneSameInstant(destinationTimeZone);

        // Calculate the duration between the converted times
        Duration duration = Duration.between(startDest, endDest);

        // Format and print the calculated duration
        DateTimeFormatter formatter = DateTimeFormatter.ofPattern("HH:mm:ss");
        System.out.println("Duration: " + duration.getSeconds() + " seconds (" + duration.toMinutesPart() + " minutes " + duration.toSecondsPart() + " seconds)");
    }
}
```

