      ringNoise: 0.3 * scale,
    };

    // Check if any existing planet is within the minimum distance
    let hasConflict = false;
    for (let I = 0; I < planets.length; i++) {
      const otherPlanet = planets[i];
      for (let j = 0; j < 3; j++) {
        if (Math.abs(otherPlanet.position[j] - planet.position[j]) < minDistance) {
          hasConflict = true;
          break;
        }
      }
      if (hasConflict) break;
    }

    if (!hasConflict) {
      planets.push(planet);
    }
  }

  return planets;
};
```

