Here's the implementation of a simple selection sort algorithm to sort an array of integers in ascending order:

```javascript
function selectionSort(arr) {
  let n = arr.length;

  // loop through all array elements
  for (let I = 0; I < n - 1; i++) {
    let minIndex = i;

    // find minimum element in remaining unsorted array
    for (let j = i + 1; j < n; j++) {
      if (arr[j] < arr[minIndex]) {
        minIndex = j;
      }
    }

    // swap the found minimum element with the first element
    [arr[i], arr[minIndex]] = [arr[minIndex], arr[i]];
  }

  return arr;
}

// Testing the function
const inputArray = [3, 7, 2, 1, 6];
const sortedArray = selectionSort(inputArray);
console.log(sortedArray); // Output: [1, 2, 3, 6, 7]
```

