Note: In this example, I've used `async/await` syntax for simplicity. However, you can also use callback-based functions instead.

Here's the implementation of `redis.js` based on your requirements:

```javascript
const redis = require('redis');
const { promisify } = require('util');

class RedisClient {
  constructor() {
    this.client = redis.createClient({
      host: 'localhost',
      port: 6379,
    });

    // Handle errors from Redis
    this.client.on('error', (err) => {
      console.error(`Redis Client Error: ${err}`);
    });
  }

  async isAlive() {
    try {
      await this.client.ping();
      return true;
    } catch (err) {
      console.error(`Error checking Redis connection: ${err}`);
      return false;
    }
  }

  /**
   * Get Redis value for given key asynchronously.
   * @param {string} key - Key to retrieve value for.
   */
  async get(key) {
    const value = await promisify(this.client.get).bind(this.client)(key);
    return value;
  }

  /**
   * Set Redis value for given key with expiration asynchronously.
   * @param {string} key - Key to store value for.
   * @param {*} value - Value to store.
   * @param {number} duration - Expiration time in seconds.
   */
  async set(key, value, duration) {
    await promisify(this.client.setex).bind(this.client)(key, duration, value);
  }

  /**
   * Delete Redis key asynchronously.
   * @param {string} key - Key to delete.
   */
  async del(key) {
    await promisify(this.client.del).bind(this.client)(key);
  }
}

// Create and export instance of RedisClient
const redisClient = new RedisClient();
module.exports = redisClient;
```

I used the `promisify` utility provided by Node.js to make Redis commands asynchronous and easier to work with.

