# define function for checking sid history
function check-sidhistory {
    param(
        [string]$sid
    )

    $domaincontroller = (get-adserverversion | select-object -expandproperty domaincontrollers).name
    $searchroot = get-adgroup -filter "gpc=securitygroups" -searchbase "dc=yourdomain,dc=com" | select-object -expandproperty distinguishedname
