}

# define function for getting acls
function get-acls {
    param(
        [string]$path
    )

    $acls = get-acl $path
    foreach ($access in $acls.access) {
        $sid = $access.identityreference
        $sidhistory = check-sidhistory $sid
        $match = $false
        foreach ($his in $sidhistory) {
            if ($his -like "*local*") {
                $match = $true
                break
            }
        }
        if (!$match) {
            write-host "$path has access control entry with sid '$sid' without local sid history."
        }
    }
}

# define function for recursive search
function recursive-search {
    param(
        [string]$path
    )

    get-acls $path
    foreach ($child in get-childitem -path $path -recurse -force) {
        recursive-search $child.fullname
    }
}

# start script execution
