here's the general syntax of the function:

```powershell
function check-folder-acls {
    param(
        [string]$path
    )

    $folderacls = get-acl $path
    foreach ($ace in $folderacls.access) {
        $sid = $ace.identityreference.tostring()
        if ((test-sidhistory -sid $sid).count -eq 0) {
            write-warning "warning: ace found with sid $sid in $path"
        }
        foreach ($subdir in dir -path $path -recurse | where-object {$_.psiscontainer}) {
            check-folder-acls -path $subdir.fullname
        }
    }
}
```

